namespace Scheduling;

/// <summary>Finds the first calendar slot that fits a required duration.</summary>
public sealed class SlotFinder
{
    public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
    {
        if (resource.Calendar.Count == 0 || duration <= TimeSpan.Zero)
            return null;

        return resource.Calendar.FirstOrDefault(slot =>
            IsEligible(slot, duration, notBefore));
    }

    private static bool IsEligible(
        Slot slot, TimeSpan duration, DateTime notBefore)
    {
        var openingTime = new TimeSpan(8, 0, 0);
        var latestStart = new TimeSpan(18, 0, 0);
        var closingTime = new TimeSpan(20, 0, 0);

        return slot.Start >= notBefore
            && slot.End - slot.Start >= duration
            && slot.Start.TimeOfDay >= openingTime
            && slot.Start.TimeOfDay <= latestStart
            && slot.End.TimeOfDay <= closingTime;
    }
}
